interface NotifierPlugin { notify(payload:any): Promise<void> }
class Notifier {
  private plugins: NotifierPlugin[] = [];
  register(p: NotifierPlugin) { this.plugins.push(p); }
  async notifyAll(payload:any) { for (const p of this.plugins) await p.notify(payload); }
}

